#[derive(Debug, Clone, Copy)]
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

pub fn terceiro(fila: &Vec<Ponto>) -> i32 {
    let terceiro_ponto = fila[2];
    terceiro_ponto.x
}

