use desafio::ponto_de;
use desafio::terceiro;

#[test]
fn testa_a_abscissa_do_terceiro_ponto() {
    let fila = vec![ponto_de(1, 2), ponto_de(4, 6), ponto_de(5, 7)];
    assert_eq!(terceiro(&fila), 5);
}

#[test]
fn testa_o_terceiro_da_segunda_lista() {
    let fila = vec![ponto_de(9, 8), ponto_de(3, 4), ponto_de(2, 1)];
    assert_eq!(terceiro(&fila), 2);
}
